import { MessageChannel } from 'node:worker_threads';

async function main(): Promise<void> {
  const carrier = new MessageChannel();
  const inner = new MessageChannel();
  const carrierQueue: any[] = [];
  carrier.port2.on('message', (m: any): void => { carrierQueue.push(m); });
  const next = async (queue: any[]): Promise<any> => {
    while (queue.length === 0) { await new Promise<void>((resolve: () => void): void => { setTimeout(resolve, 1); }); }
    return queue.shift();
  };
  inner.port2.postMessage('q1');
  inner.port2.postMessage('q2');
  carrier.port1.postMessage({ tag: 'moved', p: inner.port1 }, [inner.port1]);
  const msg: any = await next(carrierQueue);
  console.log('moved', msg.tag, msg.p === inner.port1, typeof msg.p.postMessage);
  console.log('sender copy', inner.port1.postMessage('after'));
  const movedQueue: any[] = [];
  msg.p.on('message', (v: any): void => { movedQueue.push(v); });
  console.log('moved got', await next(movedQueue));
  console.log('moved got', await next(movedQueue));
  const peerQueue: any[] = [];
  inner.port2.on('message', (v: any): void => { peerQueue.push(v); });
  msg.p.postMessage('back');
  console.log('peer got', await next(peerQueue));
  inner.port2.close();
  carrier.port1.close();
  carrier.port2.close();
  console.log('done');
}
